import { knots, inHg, hPa } from './units.ts';
import type { Station } from './main.ts';

export const DESCRIPTORS: Record<string, string> = {
  MI: 'shallow',
  BC: 'patches',
  PR: 'partial',
  DR: 'low drifting',
  BL: 'blowing',
  SH: 'showers',
  TS: 'thunderstorm',
  FZ: 'freezing',
};
export const PHENOMENA: Record<string, string> = {
  DZ: 'drizzle',
  RA: 'rain',
  SN: 'snow',
  SG: 'snow grains',
  IC: 'ice crystals',
  PL: 'ice pellets',
  GR: 'hail',
  GS: 'small hail',
  UP: 'unknown precipitation',
  BR: 'mist',
  FG: 'fog',
  FU: 'smoke',
  VA: 'volcanic ash',
  DU: 'dust',
  SA: 'sand',
  HZ: 'haze',
  PY: 'spray',
  PO: 'dust whirls',
  SQ: 'squalls',
  FC: 'funnel cloud',
  SS: 'sandstorm',
  DS: 'duststorm',
};
export const PRECIPITATION = new Set(['DZ', 'RA', 'SN', 'SG', 'IC', 'PL', 'GR', 'GS', 'UP']);
export const AMOUNTS: Record<string, string> = {
  FEW: 'few',
  SCT: 'scattered',
  BKN: 'broken',
  OVC: 'overcast',
};
export const CLEAR: Record<string, string> = {
  SKC: 'sky clear',
  CLR: 'clear below 12000 ft',
  NSC: 'no significant cloud',
};
export const INTENSITIES: Record<string, string> = { '-': 'light', '+': 'heavy', VC: 'nearby' };
const WEATHER_CODES = new Set([...Object.keys(DESCRIPTORS), ...Object.keys(PHENOMENA)]);
export interface Wind {
  direction: number | null;
  variable: boolean;
  calm: boolean;
  speed: number;
  gust: number | null;
  unit: 'KT' | 'MPS';
}
export interface MileVisibility {
  kind: 'mile';
  whole: number;
  numerator: number;
  denominator: number;
  qualifier: string;
  mixed: boolean;
  fractional: boolean;
}
export type Visibility =
  | MileVisibility
  | { kind: 'cavok'; meters: number; qualifier: string }
  | { kind: 'meter'; meters: number; qualifier: string; code: string };
export interface Reading {
  qualifier: string;
  value: number;
}
export interface RVR {
  runway: string;
  first: Reading;
  second: Reading | null;
  unit: 'ft' | 'm';
  trend: string | null;
}
export interface Weather {
  raw: string;
  nsw: boolean;
  intensity: string;
  codes: string[];
  descriptor: string | null;
  phenomena: string[];
}
export interface Cloud {
  raw: string;
  amount: string;
  height: number | null;
  suffix: string;
}
export interface Temperature {
  temperature: number;
  dewPoint: number;
}
export interface Pressure {
  unit: 'A' | 'Q';
  value: number;
  inHg: number;
  hPa: number;
}
export interface WeatherState {
  wind: Wind | null;
  visibility: Visibility | null;
  weather: Weather[] | null;
  cloud: Cloud[] | null;
}
export interface Section extends WeatherState {
  context: 'main' | 'trend' | 'base' | 'change';
  modifier: 'AUTO' | 'COR' | null;
  variation: [number, number] | null;
  rvr: RVR[];
  temperature: Temperature | null;
  pressure: Pressure | null;
  noTrend: true | null;
}
interface GroupValues {
  modifier: 'AUTO' | 'COR';
  wind: Wind;
  variation: [number, number];
  visibility: Visibility;
  rvr: RVR;
  weather: Weather;
  cloud: Cloud;
  temperature: Temperature;
  pressure: Pressure;
  noTrend: true;
}
export type GroupKind = keyof GroupValues;
export type ParsedGroup = { [K in GroupKind]: { kind: K; value: GroupValues[K] } }[GroupKind];
export interface Slot {
  kind: GroupKind;
  repeat: boolean;
  test: (text: string) => ParsedGroup | null;
}
export function section(context: Section['context']): Section {
  return {
    context,
    modifier: null,
    wind: null,
    variation: null,
    visibility: null,
    rvr: [],
    weather: null,
    cloud: null,
    temperature: null,
    pressure: null,
    noTrend: null,
  };
}
function visibilityFormat(text: string): Visibility | null {
  if (text === 'CAVOK') return { kind: 'cavok', meters: 10000, qualifier: 'P' };
  if (/^\d{4}$/.test(text)) {
    const value = Number(text);
    return {
      kind: 'meter',
      meters: value === 9999 ? 10000 : value,
      qualifier: value === 9999 ? 'P' : '',
      code: text,
    };
  }
  let match = /^(\d) (\d)\/(\d{1,2})SM$/.exec(text);
  if (match) {
    return {
      kind: 'mile',
      whole: Number(match[1]),
      numerator: Number(match[2]),
      denominator: Number(match[3]),
      qualifier: '',
      mixed: true,
      fractional: true,
    };
  }
  match = /^([MP]?)(?:(\d{1,2})|(\d)\/(\d{1,2}))SM$/.exec(text);
  return match
    ? {
        kind: 'mile',
        qualifier: match[1],
        whole: Number(match[2] ?? 0),
        numerator: Number(match[3] ?? 0),
        denominator: Number(match[4] ?? 1),
        mixed: false,
        fractional: match[3] !== undefined,
      }
    : null;
}
function weatherFormat(text: string): Weather | null {
  if (text === 'NSW') {
    return { raw: text, nsw: true, intensity: '', codes: [], descriptor: null, phenomena: [] };
  }
  let intensity = '';
  let body = text;
  if (body.startsWith('VC')) {
    intensity = 'VC';
    body = body.slice(2);
  } else if (body.startsWith('-') || body.startsWith('+')) {
    intensity = body[0];
    body = body.slice(1);
  }
  if (!body.length || body.length % 2 !== 0) return null;
  const codes: string[] = [];
  for (let index = 0; index < body.length; index += 2) {
    const code = body.slice(index, index + 2);
    if (!WEATHER_CODES.has(code)) return null;
    codes.push(code);
  }
  const descriptor = Object.hasOwn(DESCRIPTORS, codes[0]) ? codes[0] : null;
  return {
    raw: text,
    nsw: false,
    intensity,
    codes,
    descriptor,
    phenomena: descriptor === null ? codes : codes.slice(1),
  };
}
export function format(kind: GroupKind, text: string): ParsedGroup | null {
  let match: RegExpExecArray | null;
  switch (kind) {
    case 'modifier':
      return text === 'AUTO' || text === 'COR' ? { kind, value: text } : null;
    case 'wind':
      match = /^(\d{3}|VRB)(\d{2,3})(?:G(\d{2,3}))?(KT|MPS)$/.exec(text);
      return match
        ? {
            kind,
            value: {
              direction: match[1] === 'VRB' ? null : Number(match[1]),
              variable: match[1] === 'VRB',
              speed: Number(match[2]),
              gust: match[3] === undefined ? null : Number(match[3]),
              unit: match[4] === 'MPS' ? 'MPS' : 'KT',
              calm: match[1] === '000',
            },
          }
        : null;
    case 'variation':
      match = /^(\d{3})V(\d{3})$/.exec(text);
      return match ? { kind, value: [Number(match[1]), Number(match[2])] } : null;
    case 'visibility': {
      const value = visibilityFormat(text);
      return value === null ? null : { kind, value };
    }
    case 'rvr':
      match = /^R(\d{2}[LCR]?)\/([MP]?)(\d{4})(?:V([MP]?)(\d{4}))?(FT)?([UDN])?$/.exec(text);
      return match
        ? {
            kind,
            value: {
              runway: match[1],
              first: { qualifier: match[2], value: Number(match[3]) },
              second:
                match[5] === undefined ? null : { qualifier: match[4], value: Number(match[5]) },
              unit: match[6] ? 'ft' : 'm',
              trend: match[7] ?? null,
            },
          }
        : null;
    case 'weather': {
      const value = weatherFormat(text);
      return value === null ? null : { kind, value };
    }
    case 'cloud':
      if (Object.hasOwn(CLEAR, text)) {
        return { kind, value: { raw: text, amount: text, height: null, suffix: '' } };
      }
      match = /^(FEW|SCT|BKN|OVC)(\d{3})(CB|TCU)?$/.exec(text);
      if (match) {
        return {
          kind,
          value: {
            raw: text,
            amount: match[1],
            height: Number(match[2]) * 100,
            suffix: match[3] ?? '',
          },
        };
      }
      match = /^VV(\d{3})$/.exec(text);
      return match
        ? { kind, value: { raw: text, amount: 'VV', height: Number(match[1]) * 100, suffix: '' } }
        : null;
    case 'temperature':
      match = /^(M?)(\d{2})\/(M?)(\d{2})$/.exec(text);
      return match
        ? {
            kind,
            value: {
              temperature: Number(match[2]) * (match[1] ? -1 : 1),
              dewPoint: Number(match[4]) * (match[3] ? -1 : 1),
            },
          }
        : null;
    case 'pressure':
      match = /^([AQ])(\d{4})$/.exec(text);
      if (!match) return null;
      return {
        kind,
        value: {
          unit: match[1] === 'A' ? 'A' : 'Q',
          value: Number(match[2]),
          inHg: match[1] === 'A' ? Number(match[2]) : inHg(Number(match[2])),
          hPa: match[1] === 'Q' ? Number(match[2]) : hPa(Number(match[2])),
        },
      };
    case 'noTrend':
      return text === 'NOSIG' ? { kind, value: true } : null;
  }
}
export function valid(candidate: ParsedGroup, current: Section, station: Station): boolean {
  const { kind, value } = candidate;
  switch (kind) {
    case 'wind':
      if (value.variable) {
        if (value.speed < 1) return false;
      } else if (
        value.direction === null ||
        value.direction > 360 ||
        value.direction % 10 !== 0 ||
        (value.direction === 0) !== (value.speed === 0)
      ) {
        return false;
      }
      return value.gust === null || (!value.calm && value.gust > value.speed);
    case 'variation':
      return (
        value.every((direction) => direction >= 10 && direction <= 360 && direction % 10 === 0) &&
        value[0] !== value[1] &&
        current.wind !== null &&
        !current.wind.variable &&
        !current.wind.calm
      );
    case 'visibility':
      return (
        value.kind !== 'mile' ||
        (!value.fractional
          ? value.whole >= 1
          : [2, 4, 8, 16].includes(value.denominator) &&
            value.numerator >= 1 &&
            value.numerator < value.denominator &&
            (!value.mixed || value.whole >= 1))
      );
    case 'rvr':
      return (
        station.runways.some((runway) => runway.name === value.runway) &&
        (value.second === null || value.first.value < value.second.value)
      );
    case 'weather': {
      const accepted = current.weather ?? [];
      if (accepted.length >= 3 || accepted.some((weather) => weather.nsw)) return false;
      if (value.nsw) return accepted.length === 0 && ['trend', 'change'].includes(current.context);
      if (
        value.phenomena.some((code) => !Object.hasOwn(PHENOMENA, code)) ||
        new Set(value.phenomena).size !== value.phenomena.length
      ) {
        return false;
      }
      if (value.phenomena.length === 0 && value.descriptor !== 'TS' && value.descriptor !== 'SH') {
        return false;
      }
      if (
        ['-', '+'].includes(value.intensity) &&
        !value.phenomena.some((code) => PRECIPITATION.has(code))
      ) {
        return false;
      }
      return value.phenomena.length < 2 || value.phenomena.every((code) => PRECIPITATION.has(code));
    }
    case 'cloud': {
      const previous = current.cloud?.at(-1);
      return (
        !previous ||
        (Object.hasOwn(AMOUNTS, value.amount) &&
          Object.hasOwn(AMOUNTS, previous.amount) &&
          value.height !== null &&
          previous.height !== null &&
          value.height > previous.height)
      );
    }
    case 'temperature':
      return value.dewPoint <= value.temperature;
    case 'pressure':
      return value.unit === 'A'
        ? value.value >= 2500 && value.value <= 3150
        : value.value >= 850 && value.value <= 1070;
    default:
      return true;
  }
}
export function accept(current: Section, candidate: ParsedGroup): void {
  const { kind, value } = candidate;
  switch (kind) {
    case 'wind':
      current.wind =
        value.unit === 'MPS'
          ? {
              ...value,
              speed: knots(value.speed),
              gust: value.gust === null ? null : knots(value.gust),
              unit: 'KT',
            }
          : value;
      break;
    case 'visibility':
      current.visibility = value;
      if (value.kind === 'cavok') {
        current.weather = [];
        current.cloud = [];
      }
      break;
    case 'rvr':
      current.rvr.push(value);
      break;
    case 'weather':
      (current.weather ??= []).push(value);
      break;
    case 'cloud':
      (current.cloud ??= []).push(value);
      break;
    case 'modifier':
      current.modifier = value;
      break;
    case 'variation':
      current.variation = value;
      break;
    case 'temperature':
      current.temperature = value;
      break;
    case 'pressure':
      current.pressure = value;
      break;
    case 'noTrend':
      current.noTrend = value;
      break;
  }
}

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import * as groups from './groups.ts';
import * as metar from './metar.ts';
import * as taf from './taf.ts';
import * as verification from './verification.ts';
import {
  Calendar,
  floorDiv,
  pad,
  sin,
  cos,
  mileFraction,
  meterValue,
  compareVisibility,
  fraction,
} from './units.ts';
import type {
  Cloud,
  MileVisibility,
  ParsedGroup,
  Pressure,
  Reading,
  RVR,
  Section,
  Slot,
  Visibility,
  Weather,
  WeatherState,
  Wind,
} from './groups.ts';

export interface Station {
  code: string;
  elevation: number;
  runways: { name: string; heading: number }[];
  name: string;
}
interface Params {
  year: number;
  month: number;
  crosswind: number;
  tailwind: number;
  verify: string[];
}
interface RawReport {
  number: number;
  words: string[];
}
export interface Group {
  text: string;
  position: number;
}
export type ErrorRecorder = (position: number, reason: string, text?: string | null) => void;
interface ReportError {
  report: number;
  position: number;
  content: string;
}
export type Category = 'VFR' | 'MVFR' | 'IFR' | 'LIFR';
export interface CategorizedState extends WeatherState {
  category: Category;
}
interface Header {
  number: number;
  station: Station;
  time: number;
  bodyStart: number;
}
export interface ObservationHeader extends Header {
  kind: 'METAR' | 'SPECI';
}
export interface ForecastHeader extends Header {
  kind: 'TAF';
  modifier: 'AMD' | 'COR' | null;
  issueDay: number;
  start: number;
  end: number;
}
interface Component {
  head: number;
  cross: number;
}
interface RunwayWind {
  name: string;
  mean: Component;
  gust: Component | null;
  usable: boolean;
}
interface RunwayWinds {
  runways: RunwayWind[];
  preferred: RunwayWind | null;
}
export interface Observation extends ObservationHeader {
  main: Section & CategorizedState & { ceiling: number | null };
  trends: (metar.RawTrend & { state: Section })[];
  remarks: metar.Remarks;
  pressureAltitude: number | null;
  densityAltitude: number | null;
  runwayWinds: RunwayWinds | null;
  speciReasons: string[];
}
export interface Forecast extends ForecastHeader {
  base: Section;
  changes: taf.Change[];
  timeline: Map<number, taf.TimelineHour>;
}
type Report = Observation | Forecast;
const CATEGORIES = verification.CATEGORIES;
const readLines = (filename: string) =>
  readFileSync(join('input', filename), 'ascii').split('\n').slice(0, -1);

function readInputs(): { stations: Map<string, Station>; params: Params; reports: RawReport[] } {
  const stations = new Map<string, Station>();
  for (const line of readLines('stations.txt')) {
    const [code, elevation, runwayList, ...name] = line.split(' ');
    const runways = runwayList.split(',').map((entry) => {
      const [runwayName, heading] = entry.split('/');
      return { name: runwayName, heading: Number(heading) };
    });
    stations.set(code, { code, elevation: Number(elevation), runways, name: name.join(' ') });
  }
  const settings = new Map(
    readLines('params.txt').map((line): [string, string[]] => {
      const [name, ...values] = line.split(' ');
      return [name, values];
    }),
  );
  const params: Params = {
    year: Number(settings.get('YEAR')![0]),
    month: Number(settings.get('MONTH')![0]),
    crosswind: Number(settings.get('CROSSWIND_LIMIT')![0]),
    tailwind: Number(settings.get('TAILWIND_LIMIT')![0]),
    verify: settings.get('VERIFY')!,
  };
  const reports: RawReport[] = [];
  for (const line of readLines('reports.txt')) {
    const words = line.replace(/^ +/, '').split(' ');
    if (line.startsWith(' ')) reports[reports.length - 1].words.push(...words);
    else reports.push({ number: reports.length + 1, words });
  }
  return { stations, params, reports };
}
function errorRecorder(errors: ReportError[], reportNumber: number): ErrorRecorder {
  return (position, reason, text = null) => {
    errors.push({
      report: reportNumber,
      position,
      content: reason + (text === null ? '' : ` "${text}"`),
    });
  };
}
function parseHeader(
  raw: RawReport,
  stations: Map<string, Station>,
  calendar: Calendar,
  error: ErrorRecorder,
): ObservationHeader | ForecastHeader | null {
  const words = raw.words;
  const kind = words[0];
  if (kind !== 'METAR' && kind !== 'SPECI' && kind !== 'TAF') {
    error(1, 'rejected report, invalid type', kind);
    return null;
  }
  let cursor = 1;
  let modifier: ForecastHeader['modifier'] = null;
  if (kind === 'TAF' && (words[cursor] === 'AMD' || words[cursor] === 'COR')) {
    modifier = words[cursor] === 'AMD' ? 'AMD' : 'COR';
    cursor++;
  }
  const required = (item: string): string | null => {
    if (cursor === words.length) {
      error(words.length + 1, `rejected report, missing ${item}`);
      return null;
    }
    return words[cursor];
  };
  const stationWord = required('station');
  if (stationWord === null) return null;
  const station = stations.get(stationWord);
  if (!station) {
    error(cursor + 1, 'rejected report, invalid station', stationWord);
    return null;
  }
  cursor++;
  const timeWord = required('time');
  if (timeWord === null) return null;
  const time = calendar.observationTime(timeWord);
  if (time === null) {
    error(cursor + 1, 'rejected report, invalid time', timeWord);
    return null;
  }
  cursor++;
  if (kind !== 'TAF') return { number: raw.number, kind, station, time, bodyStart: cursor };
  const validityWord = required('validity');
  if (validityWord === null) return null;
  const issueDay = floorDiv(time, 1440) + 1;
  const period = calendar.period(validityWord, issueDay, 1800);
  if (period === null) {
    error(cursor + 1, 'rejected report, invalid validity', validityWord);
    return null;
  }
  return {
    number: raw.number,
    kind,
    modifier,
    station,
    time,
    issueDay,
    ...period,
    bodyStart: cursor + 1,
  };
}
function joinGroups(words: string[], start: number): Group[] {
  const result: Group[] = [];
  for (let index = start; index < words.length; index++) {
    const position = index + 1;
    let text = words[index];
    if (/^\d$/.test(text) && index + 1 < words.length && /^\d\/\d{1,2}SM$/.test(words[index + 1])) {
      text += ' ' + words[++index];
    }
    result.push({ text, position });
  }
  return result;
}
function matchSection(
  body: Group[],
  slots: Slot[],
  context: Section['context'],
  station: Station,
  error: ErrorRecorder,
): Section {
  const section = groups.section(context);
  let current = 0;
  for (const group of body) {
    let found = current;
    let candidate: ParsedGroup | null = null;
    for (; found < slots.length; found++) {
      candidate = slots[found].test(group.text);
      if (candidate !== null) break;
    }
    if (candidate === null) {
      const earlier = slots.slice(0, current).some((slot) => slot.test(group.text) !== null);
      error(group.position, earlier ? 'out of order group' : 'unknown group', group.text);
      continue;
    }
    if (!groups.valid(candidate, section, station)) {
      error(group.position, 'invalid group', group.text);
      continue;
    }
    groups.accept(section, candidate);
    current =
      candidate.kind === 'visibility' && candidate.value.kind === 'cavok'
        ? slots.findIndex((slot) => slot.kind === 'cloud') + 1
        : found + (slots[found].repeat ? 0 : 1);
  }
  return section;
}
function ceiling(state: WeatherState): number | null {
  return (
    (state.cloud ?? []).find((cloud) => ['BKN', 'OVC', 'VV'].includes(cloud.amount))?.height ?? null
  );
}
function flightCategory(state: WeatherState): Category {
  const height = ceiling(state);
  const visibility = state.visibility === null ? null : mileFraction(state.visibility);
  const less = (value: number) => visibility !== null && visibility[0] < value * visibility[1];
  const atMost = (value: number) => visibility !== null && visibility[0] <= value * visibility[1];
  if ((height !== null && height < 500) || less(1)) return 'LIFR';
  if ((height !== null && height < 1000) || less(3)) return 'IFR';
  if ((height !== null && height <= 3000) || atMost(5)) return 'MVFR';
  return 'VFR';
}
function components(direction: number, heading: number, speed: number): Component {
  const angle = direction - heading;
  return { head: floorDiv(speed * cos(angle), 1000), cross: floorDiv(speed * sin(angle), 1000) };
}
function runwayWinds(wind: Wind | null, station: Station, params: Params): RunwayWinds | null {
  if (wind === null || wind.variable || wind.calm || wind.direction === null) return null;
  const runways: RunwayWind[] = [];
  let preferred: RunwayWind | null = null;
  for (const runway of station.runways) {
    const mean = components(wind.direction, runway.heading, wind.speed);
    const gust = wind.gust === null ? null : components(wind.direction, runway.heading, wind.gust);
    const deciding = gust ?? mean;
    const usable =
      Math.abs(deciding.cross) <= params.crosswind && -deciding.head <= params.tailwind;
    const result = { name: runway.name, mean, gust, usable };
    runways.push(result);
    if (usable && (preferred === null || mean.head > preferred.mean.head)) preferred = result;
  }
  return { runways, preferred };
}
function windChanges(earlier: Wind | null, later: Wind | null, alpha: number): string[] {
  if (earlier === null || later === null) return [];
  const reasons: string[] = [];
  if (
    !earlier.variable &&
    !earlier.calm &&
    !later.variable &&
    !later.calm &&
    earlier.direction !== null &&
    later.direction !== null &&
    Math.max(earlier.speed, later.speed) >= 10
  ) {
    const difference = Math.abs(earlier.direction - later.direction) % 360;
    if (Math.min(difference, 360 - difference) >= alpha) reasons.push('wind shift');
  }
  if (Math.abs(earlier.speed - later.speed) >= 10) reasons.push('wind speed');
  return reasons;
}
function speciCheck(previous: Observation | undefined, report: Observation): string[] {
  if (previous === undefined) return ['no previous report'];
  const before = previous.main;
  const after = report.main;
  const reasons: string[] = [];
  if (before.category !== after.category) {
    reasons.push(`category ${before.category} to ${after.category}`);
  }
  reasons.push(...windChanges(before.wind, after.wind, 45));
  const thunderstorm = (state: WeatherState) =>
    (state.weather ?? []).some((weather) => weather.descriptor === 'TS');
  const freezing = (state: WeatherState) =>
    (state.weather ?? []).some(
      (weather) =>
        weather.descriptor === 'FZ' &&
        weather.phenomena.some((code) => code === 'DZ' || code === 'RA'),
    );
  if (thunderstorm(before) !== thunderstorm(after)) {
    reasons.push(`thunderstorm ${thunderstorm(after) ? 'began' : 'ended'}`);
  }
  if (freezing(before) !== freezing(after)) {
    reasons.push(`freezing precipitation ${freezing(after) ? 'began' : 'ended'}`);
