function decodeObservation(
  header: ObservationHeader,
  body: Group[],
  params: Params,
  error: ErrorRecorder,
): Observation {
  const parts = metar.splitBody(body);
  const state = matchSection(parts.main, metar.MAIN_SLOTS, 'main', header.station, error);
  const main = { ...state, ceiling: ceiling(state), category: flightCategory(state) };
  const trends = metar.readTrends(parts.trends, error).map((trend) => ({
    ...trend,
    state: matchSection(trend.groups, taf.SLOTS, 'trend', header.station, error),
  }));
  const pressureAltitude =
    main.pressure === null ? null : header.station.elevation + (2992 - main.pressure.inHg) * 10;
  const densityAltitude =
    pressureAltitude === null || main.temperature === null
      ? null
      : pressureAltitude +
        floorDiv(120 * (1000 * main.temperature.temperature - 15000 + 2 * pressureAltitude), 1000);
  return {
    ...header,
    main,
    trends,
    remarks: metar.readRemarks(parts.remarks),
    pressureAltitude,
    densityAltitude,
    runwayWinds: runwayWinds(main.wind, header.station, params),
    speciReasons: [],
