    component.head < 0 ? `tailwind ${-component.head} KT` : `headwind ${component.head} KT`;
  phrase +=
    component.cross === 0
      ? ', crosswind 0 KT'
      : `, crosswind ${Math.abs(component.cross)} KT from ${component.cross > 0 ? 'right' : 'left'}`;
