function observationLines(report: Observation, calendar: Calendar): string[] {
  const main = report.main;
  const lines = [`time: ${calendar.stamp(report.time)}`];
  if (main.modifier !== null) {
    lines.push(`modifier: ${main.modifier === 'AUTO' ? 'automated' : 'corrected'}`);
  }
  let wind = main.wind === null ? 'not reported' : windPhrase(main.wind);
  if (main.variation !== null) {
    wind += `, varying between ${pad(main.variation[0], 3)} and ${pad(main.variation[1], 3)} degrees`;
  }
  lines.push(
    'wind: ' + wind,
    'visibility: ' +
      (main.visibility === null ? 'not reported' : visibilityPhrase(main.visibility)),
  );
  for (const rvr of main.rvr) lines.push('runway visual range: ' + rvrPhrase(rvr));
  for (const weather of main.weather ?? []) lines.push('weather: ' + weatherPhrase(weather));
  if (main.visibility?.kind === 'cavok') lines.push('cloud: no significant cloud');
  else if (main.cloud === null) lines.push('cloud: not reported');
  else for (const cloud of main.cloud) lines.push('cloud: ' + cloudPhrase(cloud));
  if (main.temperature === null) lines.push('temperature: not reported');
  else {
    const { temperature, dewPoint } = main.temperature;
    lines.push(
      `temperature: ${temperature} C, dew point ${dewPoint} C, spread ${temperature - dewPoint} C`,
    );
  }
  lines.push(
    'altimeter: ' + (main.pressure === null ? 'not reported' : pressurePhrase(main.pressure)),
  );
  if (main.noTrend !== null) lines.push('trend: no significant change');
  const timeWords = { FM: 'from', TL: 'until', AT: 'at' };
  for (const trend of report.trends) {
    let phrase = trend.kind === 'BECMG' ? 'becoming' : 'temporarily';
    for (const time of trend.times) {
      phrase += ` ${timeWords[time.kind]} ${pad(time.hour, 2)}:${pad(time.minute, 2)}Z`;
    }
    lines.push(`trend: ${phrase}: ${stateSummary(trend.state)}`);
  }
  for (const pressure of report.remarks.pressures) {
    lines.push(`sea level pressure: ${decimalTenth(pressure)} hPa`);
  }
  for (const temperature of report.remarks.temperatures) {
    lines.push(
      `precise temperature: ${decimalTenth(temperature.temperature)} C, dew point ${decimalTenth(temperature.dewPoint)} C`,
    );
  }
  lines.push(
    'ceiling: ' + (main.ceiling === null ? 'none' : `${main.ceiling} ft`),
    'flight category: ' + main.category,
  );
  lines.push(
    'pressure altitude: ' +
      (report.pressureAltitude === null ? 'not available' : `${report.pressureAltitude} ft`),
  );
  lines.push(
    'density altitude: ' +
      (report.densityAltitude === null ? 'not available' : `${report.densityAltitude} ft`),
  );
  if (report.runwayWinds === null) lines.push('runway wind: not computed');
  else {
    for (const runway of report.runwayWinds.runways) {
      let phrase = componentPhrase(runway.mean);
      if (runway.gust !== null) phrase += '; gusts ' + componentPhrase(runway.gust);
      lines.push(`runway ${runway.name}: ${phrase}`);
    }
    const usable = report.runwayWinds.runways
      .filter((runway) => runway.usable)
      .map((runway) => runway.name);
    lines.push('usable runways: ' + (usable.length ? usable.join(' ') : 'none'));
    lines.push('preferred runway: ' + (report.runwayWinds.preferred?.name ?? 'none'));
