}
function forecastLines(report: Forecast, calendar: Calendar): string[] {
  const lines = ['issued: ' + calendar.stamp(report.time)];
  if (report.modifier !== null) {
    lines.push(`modifier: ${report.modifier === 'AMD' ? 'amended' : 'corrected'}`);
  }
  lines.push(
    `valid: ${calendar.stamp(report.start)} to ${calendar.stamp(report.end)}`,
    'base: ' + stateSummary(report.base),
  );
  for (const change of report.changes) {
    const period =
      change.kind === 'FM'
        ? calendar.stamp(change.time)
        : `${calendar.stamp(change.start)} to ${calendar.stamp(change.end)}`;
