function extreme<T>(
  observations: Observation[],
  valueOf: (report: Observation) => T | null,
  compare: (a: T, b: T) => number,
): { observation: Observation; value: T } | null {
  let selected: { observation: Observation; value: T } | null = null;
  for (const observation of observations) {
    const value = valueOf(observation);
    if (value !== null && (selected === null || compare(value, selected.value) < 0)) {
      selected = { observation, value };
    }
  }
  return selected;
}
function extremeLines(observations: Observation[], calendar: Calendar): string[] {
  const temperature = (report: Observation) => report.main.temperature?.temperature ?? null;
  const strength = (wind: Wind) => wind.gust ?? wind.speed;
  const line = <T>(
    label: string,
    selected: { observation: Observation; value: T } | null,
    phrase: (value: T) => string,
  ) =>
    label +
    ': ' +
    (selected === null
      ? 'not available'
      : `${phrase(selected.value)} at ${calendar.stamp(selected.observation.time)}`);
  return [
    line(
      'lowest temperature',
      extreme(observations, temperature, (a, b) => a - b),
      (value) => `${value} C`,
    ),
    line(
      'highest temperature',
      extreme(observations, temperature, (a, b) => b - a),
      (value) => `${value} C`,
    ),
    line(
      'strongest wind',
      extreme(
        observations,
        (report) => report.main.wind,
        (a, b) => strength(b) - strength(a),
      ),
      windPhrase,
    ),
    line(
      'lowest ceiling',
      extreme(
        observations,
        (report) => report.main.ceiling,
        (a, b) => a - b,
      ),
      (value) => `${value} ft`,
    ),
    line(
      'lowest visibility',
      extreme(observations, (report) => report.main.visibility, compareVisibility),
      visibilityPhrase,
    ),
  ];
}
