  const row = (label: string, values: (number | string)[]) =>
    label.padEnd(8, ' ') + values.map((value) => String(value).padStart(6, ' ')).join('');
  const lines = [row('forecast', [...CATEGORIES, 'total'])];
  for (let index = 0; index < 4; index++) {
    lines.push(row(CATEGORIES[index], [...result.table[index], result.rows[index]]));
  }
  lines.push(row('total', [...result.columns, result.total]));
  return lines;
}
function amendmentLines(result: verification.Analysis, calendar: Calendar): string[] {
  const lines: string[] = [];
  for (const choice of result.choices) {
    const observed = choice.observation.main;
    const forecast = choice.forecast.prevailing;
    const reasons: string[] = [];
    if (!choice.temporaryHit) {
      reasons.push(`category ${observed.category}, forecast ${forecast.category}`);
    }
    if (
      windChanges(forecast.wind, observed.wind, 60).length &&
      observed.wind !== null &&
      forecast.wind !== null
    ) {
      reasons.push(`wind ${windCode(observed.wind)}, forecast ${windCode(forecast.wind)}`);
    }
    if (reasons.length) {
      lines.push(`amendment ${calendar.stamp(choice.observation.time)}: ${reasons.join('; ')}`);
    }
  }
  return lines;
}
function verificationBlock(
  station: Station,
  observations: Observation[],
  forecasts: Forecast[],
  calendar: Calendar,
): string[] {
  const result = verification.analyze(observations, forecasts);
  const metars = observations.filter((report) => report.kind === 'METAR').length;
  const lines = [
    `station ${station.code} (${station.name})`,
    `reports: METAR ${metars}, SPECI ${observations.length - metars}`,
    'observed categories: ' + categoryCounts(observations.map((report) => report.main)),
  ];
  lines.push(
    ...extremeLines(observations, calendar),
    `verified: ${result.total}`,
    `no forecast: ${result.noForecast}`,
  );
  lines.push(...contingencyLines(result), 'hit rate: ' + fraction(...result.hitRate));
  lines.push(
    'hit rate with temporary groups: ' + fraction(...result.temporaryHitRate),
    'heidke skill score: ' + fraction(...result.skill),
  );
  for (let index = 0; index < 4; index++) {
    const metric = result.metrics[index];
    lines.push(
      `${CATEGORIES[index]}: pod ${fraction(...metric.pod)}, far ${fraction(...metric.far)}`,
    );
  }
  for (let index = 0; index < 5; index++) {
    const bucket = result.buckets[index];
    lines.push(`hours ${index * 6}-${index * 6 + 5}: ${fraction(bucket.hits, bucket.pairs)}`);
  }
  lines.push(...amendmentLines(result, calendar));
  return lines;
}
const blockText = (blocks: string[][]) =>
  blocks.length ? blocks.map((block) => block.join('\n')).join('\n\n') + '\n' : '';
const lineText = (lines: string[]) => (lines.length ? lines.join('\n') + '\n' : '');
function main(): void {
  const { stations, params, reports: rawReports } = readInputs();
  const calendar = new Calendar(params.year, params.month);
  const reports: Report[] = [];
  const observations: Observation[] = [];
  const forecasts: Forecast[] = [];
  const errors: ReportError[] = [];
  const previous = new Map<string, Observation>();
  for (const raw of rawReports) {
    const error = errorRecorder(errors, raw.number);
    const header = parseHeader(raw, stations, calendar, error);
    if (header === null) continue;
    const body = joinGroups(raw.words, header.bodyStart);
    if (header.kind === 'TAF') {
      const report = decodeForecast(header, body, calendar, error);
      forecasts.push(report);
      reports.push(report);
    } else {
      const report = decodeObservation(header, body, params, error);
      if (report.kind === 'SPECI') {
        report.speciReasons = speciCheck(previous.get(report.station.code), report);
      }
      previous.set(report.station.code, report);
      observations.push(report);
      reports.push(report);
    }
  }
  const verificationBlocks = params.verify.map((code) =>
    verificationBlock(
      stations.get(code)!,
      observations.filter((report) => report.station.code === code),
      forecasts.filter((report) => report.station.code === code),
      calendar,
    ),
  );
  errors.sort((first, second) => first.report - second.report || first.position - second.position);
  const outputs = new Map<string, string>([
    ['decoded.txt', blockText(reports.map((report) => decodedBlock(report, calendar)))],
    [
      'categories.csv',
      lineText([
        'station,time,ceiling,visibility,category',
        ...observations.map((report) => categoriesLine(report, calendar)),
      ]),
    ],
    ['taf_timeline.txt', blockText(forecasts.map((report) => timelineBlock(report, calendar)))],
    ['verification.txt', blockText(verificationBlocks)],
    [
      'errors.txt',
      lineText(
        errors.map((error) => `report ${error.report} word ${error.position}: ${error.content}`),
      ),
    ],
  ]);
  mkdirSync('output', { recursive: true });
  for (const [name, text] of outputs) writeFileSync(join('output', name), text, 'ascii');
}
main();

import { format, type GroupKind, type Slot, type Temperature } from './groups.ts';
import type { Group, ErrorRecorder } from './main.ts';

const MAIN_KINDS: [GroupKind, boolean][] = [
  ['modifier', false],
  ['wind', false],
  ['variation', false],
  ['visibility', false],
  ['rvr', true],
  ['weather', true],
  ['cloud', true],
  ['temperature', false],
  ['pressure', false],
  ['noTrend', false],
];
export const MAIN_SLOTS = MAIN_KINDS.map(([kind, repeat]): Slot => ({
  kind,
  repeat,
  test: (text) => format(kind, text),
}));
export interface TrendTime {
  kind: 'FM' | 'TL' | 'AT';
  hour: number;
  minute: number;
}
export interface RawTrend {
  kind: 'BECMG' | 'TEMPO';
  times: TrendTime[];
  groups: Group[];
}
export interface Remarks {
  pressures: number[];
  temperatures: Temperature[];
}
const isTrend = (group: Group) => group.text === 'BECMG' || group.text === 'TEMPO';
export function splitBody(body: Group[]): { main: Group[]; trends: Group[]; remarks: Group[] } {
  const remarkIndex = body.findIndex((group) => group.text === 'RMK');
  const beforeRemarks = remarkIndex < 0 ? body : body.slice(0, remarkIndex);
  const remarks = remarkIndex < 0 ? [] : body.slice(remarkIndex + 1);
  const trendIndex = beforeRemarks.findIndex(isTrend);
  return {
    main: trendIndex < 0 ? beforeRemarks : beforeRemarks.slice(0, trendIndex),
    trends: trendIndex < 0 ? [] : beforeRemarks.slice(trendIndex),
    remarks,
  };
}
export function readTrends(groups: Group[], error: ErrorRecorder): RawTrend[] {
  const trends: RawTrend[] = [];
  let index = 0;
  while (index < groups.length) {
    const indicator = groups[index];
    let end = index + 1;
    while (end < groups.length && !isTrend(groups[end])) end++;
    let cursor = index + 1;
    let invalid = false;
    const times: TrendTime[] = [];
    while (cursor < end) {
      const match = /^(FM|TL|AT)(\d{2})(\d{2})$/.exec(groups[cursor].text);
      if (
        !match ||
        (times.length > 0 && !(times.length === 1 && times[0].kind === 'FM' && match[1] === 'TL'))
      ) {
        break;
      }
      const hour = Number(match[2]);
      const minute = Number(match[3]);
      if (hour > 23 || minute > 59) {
        error(groups[cursor].position, 'invalid period', groups[cursor].text);
        invalid = true;
        break;
      }
      const kind = match[1] === 'FM' ? 'FM' : match[1] === 'TL' ? 'TL' : 'AT';
      times.push({ kind, hour, minute });
      cursor++;
    }
    if (!invalid) {
      trends.push({
        kind: indicator.text === 'BECMG' ? 'BECMG' : 'TEMPO',
        times,
        groups: groups.slice(cursor, end),
      });
    }
    index = end;
  }
  return trends;
}
export function readRemarks(groups: Group[]): Remarks {
  const pressures: number[] = [];
  const temperatures: Temperature[] = [];
  for (const group of groups) {
    let match = /^SLP(\d{3})$/.exec(group.text);
    if (match) {
      const value = Number(match[1]);
      pressures.push((value >= 500 ? 9000 : 10000) + value);
      continue;
    }
    match = /^T([01])(\d{3})([01])(\d{3})$/.exec(group.text);
    if (match) {
      temperatures.push({
        temperature: Number(match[2]) * (match[1] === '1' ? -1 : 1),
        dewPoint: Number(match[4]) * (match[3] === '1' ? -1 : 1),
      });
    }
  }
  return { pressures, temperatures };
}

