export type Fraction = [number, number];
export interface Period {
  start: number;
  end: number;
}
export function floorDiv(numerator: number, denominator: number): number {
  const n = BigInt(numerator);
  const d = BigInt(denominator);
  const quotient = n / d;
  return Number(quotient - (n < 0n && n % d !== 0n ? 1n : 0n));
}
export const pad = (value: number, width: number) => String(value).padStart(width, '0');
export const modulo = (value: number, divisor: number) => ((value % divisor) + divisor) % divisor;
const SINE: Record<number, number> = {
  0: 0,
  10: 174,
  20: 342,
  30: 500,
  40: 643,
  50: 766,
  60: 866,
  70: 940,
  80: 985,
  90: 1000,
};
export function sin(angle: number): number {
  const y = modulo(angle, 360);
  if (y <= 90) return SINE[y];
  if (y <= 180) return SINE[180 - y];
  if (y <= 270) return -SINE[y - 180];
  return -SINE[360 - y];
}
export const cos = (angle: number) => sin(angle + 90);
export const knots = (value: number) => floorDiv(value * 1944 + 500, 1000);
export const inHg = (value: number) => floorDiv(value * 2953 + 500, 1000);
export const hPa = (value: number) => floorDiv(value * 33864 + 50000, 100000);
export function daysInMonth(year: number, month: number): number {
  if (month === 2) return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0) ? 29 : 28;
  return [4, 6, 9, 11].includes(month) ? 30 : 31;
}
export class Calendar {
  readonly year: number;
  readonly month: number;
  readonly days: number;
  readonly nextYear: number;
  readonly nextMonth: number;
  readonly nextDays: number;
  constructor(year: number, month: number) {
    this.year = year;
    this.month = month;
    this.days = daysInMonth(year, month);
    this.nextYear = month === 12 ? year + 1 : year;
    this.nextMonth = month === 12 ? 1 : month + 1;
    this.nextDays = daysInMonth(this.nextYear, this.nextMonth);
  }
  observationTime(word: string): number | null {
    const match = /^(\d{2})(\d{2})(\d{2})Z$/.exec(word);
    if (!match) return null;
    const [day, hour, minute] = match.slice(1).map(Number);
    if (day < 1 || day > this.days || hour > 23 || minute > 59) return null;
    return ((day - 1) * 24 + hour) * 60 + minute;
  }
  dayTime(day: number, hour: number, minute: number, issueDay: number): number | null {
    const following = day < issueDay;
    if (day < 1 || day > (following ? this.nextDays : this.days)) return null;
    return (following ? this.days * 1440 : 0) + ((day - 1) * 24 + hour) * 60 + minute;
  }
  period(word: string, issueDay: number, maximum: number | null = null): Period | null {
    const match = /^(\d{2})(\d{2})\/(\d{2})(\d{2})$/.exec(word);
    if (!match) return null;
    const [firstDay, firstHour, lastDay, lastHour] = match.slice(1).map(Number);
    if (firstHour > 23 || lastHour < 1 || lastHour > 24) return null;
    const start = this.dayTime(firstDay, firstHour, 0, issueDay);
    const end = this.dayTime(lastDay, lastHour, 0, issueDay);
    if (
      start === null ||
      end === null ||
      start >= end ||
      (maximum !== null && end - start > maximum)
    ) {
      return null;
    }
    return { start, end };
  }
  changeTime(word: string, issueDay: number): number | null {
    const match = /^FM(\d{2})(\d{2})(\d{2})$/.exec(word);
    if (!match) return null;
    const [day, hour, minute] = match.slice(1).map(Number);
    return hour > 23 || minute > 59 ? null : this.dayTime(day, hour, minute, issueDay);
  }
  stamp(time: number): string {
    const following = time >= this.days * 1440;
    const value = time - (following ? this.days * 1440 : 0);
    return (
      `${pad(following ? this.nextYear : this.year, 4)}-${pad(following ? this.nextMonth : this.month, 2)}` +
      `-${pad(floorDiv(value, 1440) + 1, 2)}T${pad(floorDiv(value % 1440, 60), 2)}:${pad(value % 60, 2)}Z`
    );
  }
}
export function mileFraction(visibility: Visibility): Fraction {
  return visibility.kind === 'mile'
    ? [visibility.whole * visibility.denominator + visibility.numerator, visibility.denominator]
    : [visibility.meters * 1000, 1609344];
}
export function meterValue(visibility: Visibility): number {
  if (visibility.kind !== 'mile') return visibility.meters;
  const [numerator, denominator] = mileFraction(visibility);
  return floorDiv(1609344 * numerator, 1000 * denominator);
}
export function compareVisibility(first: Visibility, second: Visibility): number {
  const [a, b] = mileFraction(first);
  const [c, d] = mileFraction(second);
  return a * d - c * b;
}
export function fraction(numerator: number, denominator: number): string {
  if (denominator === 0) return 'undefined';
  let first = Math.abs(numerator);
  let second = denominator;
  while (second !== 0) [first, second] = [second, first % second];
  return `${floorDiv(numerator, first)}/${floorDiv(denominator, first)}`;
}

import { floorDiv, type Fraction } from './units.ts';
import type { Category, Forecast, Observation } from './main.ts';
import type { TimelineHour } from './taf.ts';

export const CATEGORIES: Category[] = ['VFR', 'MVFR', 'IFR', 'LIFR'];
export interface Choice {
  observation: Observation;
  taf: Forecast;
  forecast: TimelineHour;
  hit: boolean;
  temporaryHit: boolean;
}
export interface Analysis {
  table: number[][];
  rows: number[];
  columns: number[];
  total: number;
  noForecast: number;
  choices: Choice[];
  buckets: { hits: number; pairs: number }[];
  metrics: { pod: Fraction; far: Fraction }[];
  hitRate: Fraction;
  temporaryHitRate: Fraction;
  skill: Fraction;
}
export function covers(taf: Forecast, observation: Observation): boolean {
  const hour = observation.time - (observation.time % 60);
  return taf.time <= observation.time && taf.start <= hour && hour < taf.end;
}
export function select(tafs: Forecast[], observation: Observation): Forecast | null {
  let selected: Forecast | null = null;
  for (const taf of tafs) {
    if (
      covers(taf, observation) &&
      (selected === null ||
        taf.time > selected.time ||
        (taf.time === selected.time && taf.number > selected.number))
    ) {
      selected = taf;
    }
  }
  return selected;
}
export function analyze(observations: Observation[], tafs: Forecast[]): Analysis {
  const table = Array.from({ length: 4 }, () => [0, 0, 0, 0]);
  const buckets = Array.from({ length: 5 }, () => ({ hits: 0, pairs: 0 }));
  const choices: Choice[] = [];
  let noForecast = 0;
  let hits = 0;
  let temporaryHits = 0;
  for (const observation of observations) {
    const hour = observation.time - (observation.time % 60);
    const category = observation.main.category;
    for (const taf of tafs) {
      if (!covers(taf, observation)) continue;
      const bucket = buckets[floorDiv(hour - taf.start, 360)];
      bucket.pairs++;
      if (taf.timeline.get(hour)!.prevailing.category === category) bucket.hits++;
    }
    const chosen = select(tafs, observation);
    if (chosen === null) {
      noForecast++;
      continue;
    }
    const forecast = chosen.timeline.get(hour)!;
    const forecastCategory = forecast.prevailing.category;
    const hit = forecastCategory === category;
    const temporaryHit =
      hit || forecast.temporary.some((change) => change.state.category === category);
    table[CATEGORIES.indexOf(forecastCategory)][CATEGORIES.indexOf(category)]++;
    if (hit) hits++;
    if (temporaryHit) temporaryHits++;
    choices.push({ observation, taf: chosen, forecast, hit, temporaryHit });
  }
  const rows = table.map((row) => row.reduce((sum, count) => sum + count, 0));
  const columns = CATEGORIES.map((_, index) => table.reduce((sum, row) => sum + row[index], 0));
  const total = rows.reduce((sum, count) => sum + count, 0);
  let expected = 0;
  for (let index = 0; index < 4; index++) expected += rows[index] * columns[index];
  const metrics = CATEGORIES.map((_, index): Analysis['metrics'][number] => ({
    pod: [table[index][index], columns[index]],
    far: [rows[index] - table[index][index], rows[index]],
  }));
  return {
    table,
    rows,
    columns,
    total,
    noForecast,
    choices,
    buckets,
    metrics,
    hitRate: [hits, total],
    temporaryHitRate: [temporaryHits, total],
    skill: [total * hits - expected, total * total - expected],
  };
}
